"""Quality measurements and reviewer flags. Recordings are tones generated by FFmpeg here."""

from pathlib import Path

import pytest

from app.audio import ffmpeg, quality
from app.audio.quality import Metrics
from tests.audio_fixtures import make_audio, requires_ffmpeg

CLEAN = Metrics(
    peak_dbfs=-6.0,
    rms_dbfs=-20.0,
    integrated_lufs=-23.0,
    true_peak_dbtp=-5.8,
    clipping_ratio=0.0,
    silence_ratio=0.1,
)


@pytest.mark.parametrize(
    ("changes", "duration_ms", "expected"),
    [
        ({}, 5000, set()),
        ({}, 999, {"too_short"}),
        ({"silence_ratio": 0.96}, 5000, {"silent"}),
        ({"silence_ratio": 0.95}, 5000, set()),
        ({"rms_dbfs": -45.5}, 5000, {"very_quiet"}),
        ({"rms_dbfs": None}, 5000, {"very_quiet"}),  # no signal at all
        ({"clipping_ratio": 0.0011}, 5000, {"clipping"}),
        ({"clipping_ratio": 0.001}, 5000, set()),
    ],
)
def test_flags(changes: dict[str, float | None], duration_ms: int, expected: set[str]) -> None:
    metrics = Metrics(**{**CLEAN.as_json(), **changes})  # type: ignore[arg-type]
    assert quality.flags(metrics, duration_ms, min_seconds=1) == expected


def test_a_log_without_summaries_is_an_error() -> None:
    with pytest.raises(ValueError, match="astats"):
        quality.parse("[in#0] nothing measured\n", 1000)


def analyse(path: Path, container: str, duration_ms: int) -> Metrics:
    log = ffmpeg.analysis_log(path, container, quality.FILTERS, timeout=60)
    return quality.parse(log, duration_ms)


@requires_ffmpeg
@pytest.mark.parametrize("container", ["wav", "webm", "m4a"])
def test_a_clear_tone_has_no_flags(tmp_path: Path, container: str) -> None:
    path = tmp_path / "input"
    make_audio(path, container, seconds=4)
    metrics = analyse(path, container, 4000)
    # The tone peaks at -18 dBFS; lossy encoders overshoot a little at the start.
    assert metrics.peak_dbfs is not None and -20 < metrics.peak_dbfs < -12
    assert metrics.integrated_lufs is not None and metrics.true_peak_dbtp is not None
    assert metrics.silence_ratio == 0 and metrics.clipping_ratio == 0
    assert quality.flags(metrics, 4000, min_seconds=1) == set()


@requires_ffmpeg
def test_measures_silence(tmp_path: Path) -> None:
    path = tmp_path / "input"
    tone_then_silence = "sine=frequency=220:duration=3[a];anullsrc=d=1[b];[a][b]concat=v=0:a=1"
    make_audio(path, "flac", source=tone_then_silence)
    metrics = analyse(path, "flac", 4000)
    assert metrics.silence_ratio == pytest.approx(0.25, abs=0.01)


@requires_ffmpeg
def test_digital_silence(tmp_path: Path) -> None:
    path = tmp_path / "input"
    make_audio(path, "wav", source="anullsrc=d=3")
    metrics = analyse(path, "wav", 3000)
    assert (metrics.peak_dbfs, metrics.rms_dbfs, metrics.true_peak_dbtp) == (None, None, None)
    assert quality.flags(metrics, 3000, min_seconds=1) == {"silent", "very_quiet"}


@requires_ffmpeg
def test_quiet_speech_is_not_silence(tmp_path: Path) -> None:
    path = tmp_path / "input"
    make_audio(path, "wav", source="sine=frequency=220:duration=3,volume=0.05")  # about -44 dBFS
    assert quality.flags(analyse(path, "wav", 3000), 3000, min_seconds=1) == {"very_quiet"}


@requires_ffmpeg
@pytest.mark.parametrize("container", ["wav", "webm", "mp3"])
def test_counts_clipping_in_lossless_and_lossy_files(tmp_path: Path, container: str) -> None:
    path = tmp_path / "input"
    make_audio(path, container, source="sine=frequency=220:duration=3,volume=20")
    metrics = analyse(path, container, 3000)
    assert metrics.clipping_ratio > 0.2
    assert "clipping" in quality.flags(metrics, 3000, min_seconds=1)
